use std::{fs,time::{Instant,Duration},thread};use serde_json::{Value,json};use windows_sys::Win32::{Foundation::*,System::{Threading::*,JobObjects::*,Console::*}};
fn wide(s:&str)->Vec<u16>{s.encode_utf16().chain(Some(0)).collect()}
fn quote(s:&str)->String{let mut o=String::from("\"");let mut sl=0;for c in s.chars(){if c=='\\'{sl+=1;continue;}if c=='"'{o.push_str(&"\\".repeat(sl*2+1));o.push(c);}else{o.push_str(&"\\".repeat(sl));o.push(c);}sl=0;}o.push_str(&"\\".repeat(sl*2));o.push('"');o}
struct Handle(HANDLE);impl Drop for Handle{fn drop(&mut self){unsafe{if !self.0.is_null(){CloseHandle(self.0);}}}}
fn ok(b:i32,context:&str){assert_ne!(b,0,"{}: {}",context,std::io::Error::last_os_error());}
fn main(){let args:Vec<_>=std::env::args().collect();let c:Value=serde_json::from_slice(&fs::read(&args[1]).unwrap()).unwrap();let start=Instant::now();unsafe{
 let _mutex=if let Some(name)=c["mutex"].as_str(){let h=Handle(CreateMutexW(std::ptr::null(),0,wide(name).as_ptr()));assert!(!h.0.is_null());let r=WaitForSingleObject(h.0,0);assert!(r==WAIT_OBJECT_0||r==WAIT_ABANDONED,"Workspace mutex busy");Some(h)}else{None};
 let owners:Vec<_>=c["owners"].as_array().map(|a|a.iter().map(|p|{let h=Handle(OpenProcess(PROCESS_SYNCHRONIZE,0,p.as_u64().unwrap() as u32));assert!(!h.0.is_null(),"Owner missing");h}).collect()).unwrap_or_default();
 let job=Handle(CreateJobObjectW(std::ptr::null(),std::ptr::null()));assert!(!job.0.is_null());let mut limit:JOBOBJECT_EXTENDED_LIMIT_INFORMATION=std::mem::zeroed();limit.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;ok(SetInformationJobObject(job.0,JobObjectExtendedLimitInformation,&limit as *const _ as *const _,std::mem::size_of_val(&limit) as u32),"set job limits");
 let argv:Vec<_>=c["argv"].as_array().unwrap().iter().map(|x|x.as_str().unwrap()).collect();let command=argv.iter().map(|x|quote(x)).collect::<Vec<_>>().join(" ");let mut cmd=wide(&command);let exe=wide(argv[0]);let cwd=wide(c["cwd"].as_str().unwrap());let mut si:STARTUPINFOW=std::mem::zeroed();si.cb=std::mem::size_of_val(&si) as u32;si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=GetStdHandle(STD_INPUT_HANDLE);si.hStdOutput=GetStdHandle(STD_OUTPUT_HANDLE);si.hStdError=GetStdHandle(STD_ERROR_HANDLE);for h in [si.hStdInput,si.hStdOutput,si.hStdError]{ok(SetHandleInformation(h,HANDLE_FLAG_INHERIT,HANDLE_FLAG_INHERIT),"inherit standard pipe");}let mut pi:PROCESS_INFORMATION=std::mem::zeroed();
 ok(CreateProcessW(exe.as_ptr(),cmd.as_mut_ptr(),std::ptr::null(),std::ptr::null(),1,CREATE_SUSPENDED|CREATE_NO_WINDOW,std::ptr::null(),cwd.as_ptr(),&si,&mut pi),"create suspended");let proc=Handle(pi.hProcess);let primary=Handle(pi.hThread);if AssignProcessToJobObject(job.0,proc.0)==0{TerminateProcess(proc.0,111);panic!("assign job failed {}",std::io::Error::last_os_error());}assert_ne!(ResumeThread(primary.0),u32::MAX);
 if let Some(f)=c["startedFile"].as_str(){fs::write(f,serde_json::to_vec(&json!({"pid":pi.dwProcessId,"runnerPid":std::process::id(),"assignedBeforeResume":true,"killOnJobClose":true})).unwrap()).unwrap();}
 let mut reason="process-exit";loop{if WaitForSingleObject(proc.0,25)==WAIT_OBJECT_0{break;}if c["cancelFile"].as_str().map(|f|std::path::Path::new(f).exists()).unwrap_or(false){reason="cancel-request";ok(TerminateJobObject(job.0,1223),"cancel job");break;}if owners.iter().any(|p|WaitForSingleObject(p.0,0)==WAIT_OBJECT_0){reason="owner-exit";ok(TerminateJobObject(job.0,1223),"terminate owned job");break;}if let Some(ms)=c["timeoutMs"].as_u64(){if start.elapsed().as_millis()>ms as u128{reason="timeout";ok(TerminateJobObject(job.0,1460),"terminate timeout job");break;}}}
 // The direct process may exit while grandchildren remain. Terminate the
 // whole owned job and verify zero active members before releasing its mutex.
 let mut info:JOBOBJECT_BASIC_AND_IO_ACCOUNTING_INFORMATION=std::mem::zeroed();ok(QueryInformationJobObject(job.0,JobObjectBasicAndIoAccountingInformation,&mut info as *mut _ as *mut _,std::mem::size_of_val(&info) as u32,std::ptr::null_mut()),"job accounting");if info.BasicInfo.ActiveProcesses>0{ok(TerminateJobObject(job.0,1223),"reap remaining descendants");}
 for _ in 0..400{ok(QueryInformationJobObject(job.0,JobObjectBasicAndIoAccountingInformation,&mut info as *mut _ as *mut _,std::mem::size_of_val(&info) as u32,std::ptr::null_mut()),"job completion");if info.BasicInfo.ActiveProcesses==0{break;}thread::sleep(Duration::from_millis(25));}assert_eq!(info.BasicInfo.ActiveProcesses,0,"Job failed to drain");let mut code=0;ok(GetExitCodeProcess(proc.0,&mut code),"exit code");
 if let Some(f)=c["metricsFile"].as_str(){let m=json!({"wallMs":start.elapsed().as_secs_f64()*1000.0,"reason":reason,"exitCode":code,"processes":info.BasicInfo.TotalProcesses,"activeProcesses":info.BasicInfo.ActiveProcesses,"userMs":info.BasicInfo.TotalUserTime as f64/10000.0,"kernelMs":info.BasicInfo.TotalKernelTime as f64/10000.0,"readOperations":info.IoInfo.ReadOperationCount,"readTransferBytes":info.IoInfo.ReadTransferCount,"writeOperations":info.IoInfo.WriteOperationCount,"writeTransferBytes":info.IoInfo.WriteTransferCount,"ioIsLogicalNotPhysical":true});fs::write(f,serde_json::to_vec(&m).unwrap()).unwrap();}if let Some(h)=&_mutex{ReleaseMutex(h.0);}drop(job);std::process::exit(if code==0{0}else{1});}}


